INSERT INTO clues (dish_id, order_index, text) VALUES
((SELECT id FROM dishes WHERE slug='cheese-fondue'), 1, 'A shared pot for a cold night, from the mountains of central Europe.'),
((SELECT id FROM dishes WHERE slug='cheese-fondue'), 2, 'A dairy cartel pushed it as a national dish in the 1930s, to move more of what its members made.'),
((SELECT id FROM dishes WHERE slug='cheese-fondue'), 3, 'Lose your bread cube off the long fork and table custom says you buy the next round.'),
((SELECT id FROM dishes WHERE slug='cheese-fondue'), 4, 'You rub the pot with garlic, melt gruyere and emmental into white wine, and loosen it with a shot of kirsch.'),
((SELECT id FROM dishes WHERE slug='cheese-fondue'), 5, 'Switzerland''s bubbling caquelon over a burner, ringed by long forks spearing cubes of crusty loaf.'),
((SELECT id FROM dishes WHERE slug='tartiflette'), 1, 'A baked potato gratin from the ski slopes of western Europe.'),
((SELECT id FROM dishes WHERE slug='tartiflette'), 2, 'Savoie cheesemakers dreamed it up in the 1980s to sell more reblochon, and dressed it up as an old mountain recipe.'),
((SELECT id FROM dishes WHERE slug='tartiflette'), 3, 'Mountain dialect lent it an old word for potato, though the recipe is younger than most of the ski lifts.'),
((SELECT id FROM dishes WHERE slug='tartiflette'), 4, 'You layer sliced potato with bacon, onion, cream and a splash of white wine, then crown it with a halved reblochon, rind up.'),
((SELECT id FROM dishes WHERE slug='tartiflette'), 5, 'France''s Alpine après-ski supper, bubbling brown in its baking dish with a crackling orange crust.'),
((SELECT id FROM dishes WHERE slug='irish-stew'), 1, 'A one-pot meat and root supper from northwestern Europe.'),
((SELECT id FROM dishes WHERE slug='irish-stew'), 2, 'Cottagers simmered old mutton with roots in a single pot hung over a turf fire, since the hearth held no more.'),
((SELECT id FROM dishes WHERE slug='irish-stew'), 3, 'Cooks fight over carrot: purists say mutton, spuds and onion are the whole recipe, and orange is a Dublin affectation.'),
((SELECT id FROM dishes WHERE slug='irish-stew'), 4, 'You layer lamb neck chops between rounds of potato and onion, add water and thyme, and simmer it for two hours.'),
((SELECT id FROM dishes WHERE slug='irish-stew'), 5, 'Ireland''s pale brothy bowl of floury spuds and tender meat, scattered with parsley beside a hunk of soda bread.'),
((SELECT id FROM dishes WHERE slug='bigos'), 1, 'A dark, sour meat and cabbage pot from eastern Europe.'),
((SELECT id FROM dishes WHERE slug='bigos'), 2, 'Noble hunting parties cooked it at camp from whatever they shot, which is why it still goes by hunter''s stew.'),
((SELECT id FROM dishes WHERE slug='bigos'), 3, 'Families reheat one pot for a week and swear day three is best, and the national epic poem gives it a verse.'),
((SELECT id FROM dishes WHERE slug='bigos'), 4, 'You simmer sauerkraut and fresh cabbage for hours with pork, sausage, dried mushroom, prunes and bay leaf.'),
((SELECT id FROM dishes WHERE slug='bigos'), 5, 'Poland''s brown winter hotpot, sharp and smoky, spooned from a crock beside dark rye.'),
((SELECT id FROM dishes WHERE slug='stollen'), 1, 'A heavy fruit loaf from central Europe, baked for Christmas.'),
((SELECT id FROM dishes WHERE slug='stollen'), 2, 'Saxon bakers wrote to the Pope asking to use butter during the Advent fast, and a papal letter let them.'),
((SELECT id FROM dishes WHERE slug='stollen'), 3, 'Bakers shape it to look like the swaddled Christ child, and Dresden parades a giant one through town each December.'),
((SELECT id FROM dishes WHERE slug='stollen'), 4, 'You knead raisins and candied peel into a yeast dough rich with butter and almond, and roll a log of marzipan into the middle.'),
((SELECT id FROM dishes WHERE slug='stollen'), 5, 'Germany''s snow-white holiday bread under a thick dusting of powdered sugar, cut in thin slices through Advent.'),
((SELECT id FROM dishes WHERE slug='buche-de-noel'), 1, 'A rolled chocolate cake from western Europe, made for the winter holidays.'),
((SELECT id FROM dishes WHERE slug='buche-de-noel'), 2, 'Paris pastry cooks in the 1800s swapped the great block of wood families burned on the hearth for a cake shaped like it.'),
((SELECT id FROM dishes WHERE slug='buche-de-noel'), 3, 'You drag a fork through the frosting to make bark, and little meringue mushrooms sprout along its side.'),
((SELECT id FROM dishes WHERE slug='buche-de-noel'), 4, 'You bake a thin cocoa sponge, roll it around whipped cream, and coat the outside in chocolate ganache.'),
((SELECT id FROM dishes WHERE slug='buche-de-noel'), 5, 'France''s Christmas yule log, one end cut off at a slant like a sawn branch and dusted with sugar snow.'),
((SELECT id FROM dishes WHERE slug='pan-de-muerto'), 1, 'A sugared sweet bun from Latin America, baked for an autumn holiday.'),
((SELECT id FROM dishes WHERE slug='pan-de-muerto'), 2, 'Families bake it for the first days of November, and historians still argue whether it began as a Spanish or Aztec offering.'),
((SELECT id FROM dishes WHERE slug='pan-de-muerto'), 3, 'Bakers lay dough bones across the top and a skull on the crown, and families leave a loaf on home altars for the dead.'),
((SELECT id FROM dishes WHERE slug='pan-de-muerto'), 4, 'You scent an egg-rich yeast dough with orange zest and anise, bake it, then brush it with butter and roll it in sugar.'),
((SELECT id FROM dishes WHERE slug='pan-de-muerto'), 5, 'Mexico''s bread of the dead, a round sugar-crusted bun sitting on an ofrenda among marigolds and candles.'),
((SELECT id FROM dishes WHERE slug='oden'), 1, 'A winter one-pot of simmered odds and ends from East Asia.'),
((SELECT id FROM dishes WHERE slug='oden'), 2, 'Edo vendors took a skewered tofu snack and started simmering it in broth, and the pot grew to hold dozens of items.'),
((SELECT id FROM dishes WHERE slug='oden'), 3, 'Convenience store clerks keep a heated tray of it by the till all winter, and you fish out your own pieces with tongs.'),
((SELECT id FROM dishes WHERE slug='oden'), 4, 'You simmer daikon, boiled egg, fish cake and konjac in a light dashi seasoned with soy sauce, for hours and never at a boil.'),
((SELECT id FROM dishes WHERE slug='oden'), 5, 'Japan''s steaming divided pot of broth-soaked radish and tofu pouches, eaten with a dab of hot yellow mustard.'),
((SELECT id FROM dishes WHERE slug='tangyuan'), 1, 'A warm sweet soup of dumplings from East Asia.'),
((SELECT id FROM dishes WHERE slug='tangyuan'), 2, 'Families eat them at the winter solstice and the Lantern Festival, a custom going back to the Song dynasty.'),
((SELECT id FROM dishes WHERE slug='tangyuan'), 3, 'Diners hear the word for reunion in the name, so a shared bowl on a holiday means the family came home.'),
((SELECT id FROM dishes WHERE slug='tangyuan'), 4, 'You wrap black sesame paste creamed with sugar and lard in glutinous rice dough, roll balls, and boil them until they float.'),
((SELECT id FROM dishes WHERE slug='tangyuan'), 5, 'China''s glossy white rice balls bobbing in ginger syrup, spilling dark filling when you bite.'),
((SELECT id FROM dishes WHERE slug='sarson-ka-saag'), 1, 'A slow-cooked dish of winter greens from South Asia.'),
((SELECT id FROM dishes WHERE slug='sarson-ka-saag'), 2, 'Punjabi farm households cook it in the cold months, when the leaves come straight off their own winter fields.'),
((SELECT id FROM dishes WHERE slug='sarson-ka-saag'), 3, 'Cooks pair it with a crumbly flatbread of maize, and you top it with a lump of white butter.'),
((SELECT id FROM dishes WHERE slug='sarson-ka-saag'), 4, 'You simmer bitter leaves with spinach, ginger and green chili for hours, churn them with a wooden masher, and add cornmeal.'),
((SELECT id FROM dishes WHERE slug='sarson-ka-saag'), 5, 'India''s dark green mash of mustard greens, glossy with ghee and fried garlic, scooped up with yellow corn roti.'),
((SELECT id FROM dishes WHERE slug='pot-roast'), 1, 'A Sunday beef dinner from the American Midwest.'),
((SELECT id FROM dishes WHERE slug='pot-roast'), 2, 'Depression-era families bought the cheapest chuck and let a heavy lidded kettle turn it tender over one long afternoon.'),
((SELECT id FROM dishes WHERE slug='pot-roast'), 3, 'An internet version drops a packet of ranch mix and a jar of pepperoncini on top and walks away.'),
((SELECT id FROM dishes WHERE slug='pot-roast'), 4, 'You sear a chuck in a Dutch oven, add beef broth, carrot, potato, onion, thyme and bay leaf, and braise it for hours.'),
((SELECT id FROM dishes WHERE slug='pot-roast'), 5, 'America''s Sunday dinner, a fork-tender slab sliced beside its vegetables under brown gravy.'),
((SELECT id FROM dishes WHERE slug='green-bean-casserole'), 1, 'A creamy holiday side from North America, baked in a glass dish.'),
((SELECT id FROM dishes WHERE slug='green-bean-casserole'), 2, 'Dorcas Reilly worked it out in a Campbell''s test kitchen in 1955, to sell more cream of mushroom soup.'),
((SELECT id FROM dishes WHERE slug='green-bean-casserole'), 3, 'Her family gave the original handwritten card to the National Inventors Hall of Fame, and a museum keeps it there.'),
((SELECT id FROM dishes WHERE slug='green-bean-casserole'), 4, 'You stir snapped pods into canned mushroom soup with milk, soy sauce and black pepper, then bake it under crisp fried onion.'),
((SELECT id FROM dishes WHERE slug='green-bean-casserole'), 5, 'America''s Thanksgiving side, grey-green and bubbling under a crunchy crown of canned shallots.'),
((SELECT id FROM dishes WHERE slug='kabak-tatlisi'), 1, 'A candied autumn sweet from the Middle East, served cool.'),
((SELECT id FROM dishes WHERE slug='kabak-tatlisi'), 2, 'Anatolian households make it in autumn, when the markets fill with thick-skinned winter squash sold by the slice.'),
((SELECT id FROM dishes WHERE slug='kabak-tatlisi'), 3, 'Cooks pour tahini over the top and scatter crushed walnuts, a pairing that surprises diners who expect cream.'),
((SELECT id FROM dishes WHERE slug='kabak-tatlisi'), 4, 'You bury peeled wedges in sugar with a few cloves overnight, then simmer them in their own juice until they turn glassy.'),
((SELECT id FROM dishes WHERE slug='kabak-tatlisi'), 5, 'Türkiye''s pumpkin dessert, translucent orange slabs under a drizzle of sesame paste and nut crumbs.');
