INSERT INTO drink_clues (drink_id, order_index, text) VALUES
((SELECT id FROM drinks WHERE slug='hot-buttered-rum'), 1, 'A steaming winter mug from colonial North America.'),
((SELECT id FROM drinks WHERE slug='hot-buttered-rum'), 2, 'New England distillers ran Caribbean molasses into cheap spirit, and taverns stirred it into hot water with brown sugar, clove and nutmeg.'),
((SELECT id FROM drinks WHERE slug='hot-buttered-rum'), 3, 'America''s dark amber mug, a pat melting on top into a golden slick with a cinnamon stick standing in it.'),
((SELECT id FROM drinks WHERE slug='tom-and-jerry'), 1, 'A frothy holiday mug from North America, built on a sweet batter.'),
((SELECT id FROM drinks WHERE slug='tom-and-jerry'), 2, 'A bartender and a London novelist both claim the origin. You beat eggs with sugar, then stretch a spoonful with brandy, rum and hot milk.'),
((SELECT id FROM drinks WHERE slug='tom-and-jerry'), 3, 'America''s Midwest Christmas cup, ladled from a milk-glass bowl with its name in gold, and nutmeg on the foam.'),
((SELECT id FROM drinks WHERE slug='canelazo'), 1, 'A hot fruit punch sold at street stalls in the high Andes of Latin America.'),
((SELECT id FROM drinks WHERE slug='canelazo'), 2, 'Highland vendors boil naranjilla juice with cane sugar and water, and you choose how much sugarcane aguardiente they pour in.'),
((SELECT id FROM drinks WHERE slug='canelazo'), 3, 'Ecuador''s cinnamon-steeped cup for cold nights, handed out steaming in Quito''s plazas during the December fiestas.'),
((SELECT id FROM drinks WHERE slug='coquito'), 1, 'A creamy chilled holiday drink from the Caribbean, poured into small glasses.'),
((SELECT id FROM drinks WHERE slug='coquito'), 2, 'Families on the island make it for December parties, blending white rum with coconut milk, condensed milk, cinnamon and vanilla.'),
((SELECT id FROM drinks WHERE slug='coquito'), 3, 'Puerto Rican households hand it out as gifts in recycled liquor bottles, and you sip it cold under grated nutmeg.'),
((SELECT id FROM drinks WHERE slug='champurrado'), 1, 'A hot drink from Latin America thick enough to coat the spoon.'),
((SELECT id FROM drinks WHERE slug='champurrado'), 2, 'Aztec cooks thickened cacao with ground maize before sugar arrived. Cooks now whisk masa into chocolate, milk and brown sugar.'),
((SELECT id FROM drinks WHERE slug='champurrado'), 3, 'Mexico''s December mug beside a plate of tamales, dark brown and gluey enough to grow a skin on top.'),
((SELECT id FROM drinks WHERE slug='ponche-navideno'), 1, 'A hot fruit brew ladled from a clay pot in Latin America, in winter.'),
((SELECT id FROM drinks WHERE slug='ponche-navideno'), 2, 'Families simmer it through the posadas in December, with guava, tejocote, apple, prunes and sticks of sugar cane in one big pot.'),
((SELECT id FROM drinks WHERE slug='ponche-navideno'), 3, 'Mexico''s Christmas punch, a clay mug of amber syrup with chunks of fruit and a stalk to chew.'),
((SELECT id FROM drinks WHERE slug='yuja-tea'), 1, 'A hot citrus cup from East Asia, spooned out of a jar of marmalade.'),
((SELECT id FROM drinks WHERE slug='yuja-tea'), 2, 'Households slice the bumpy citron thin in late autumn and pack it in jars with honey and sugar. You stir a spoonful into hot water.'),
((SELECT id FROM drinks WHERE slug='yuja-tea'), 3, 'Korea''s cold-season cure, a cup of cloudy gold with strands of peel left in for you to chew.'),
((SELECT id FROM drinks WHERE slug='pumpkin-spice-latte'), 1, 'A sweetened coffee-shop drink from North America, sold in autumn.'),
((SELECT id FROM drinks WHERE slug='pumpkin-spice-latte'), 2, 'A Seattle coffee chain launched it in 2003, and baristas pump a cinnamon, nutmeg and clove syrup into espresso and steamed milk.'),
((SELECT id FROM drinks WHERE slug='pumpkin-spice-latte'), 3, 'Americans line up for its return in late August, a milky orange cup under whipped cream and a dusting of cinnamon.');
